"""Initial Blue (Cooperator) constitution for PGG co-evolution.

Seed constitution emphasising generous contribution, conditional cooperation,
and punishment of free-riders.
"""


def get_constitution_rules():
    return (
        {
            "name": "Contribute Generously",
            "guidance": (
                "Each round, contribute at least 90% of your current wallet to the public pool. "
                "High contributions strongly boost the multiplied pool, maximizing productivity "
                "and keeping the free‑rider rate within your faction low."
            ),
            "summary": "Contribute at least 90% of wallet each round.",
            "priority": 1,
        },
        {
            "name": "Adaptive Contribution",
            "guidance": (
                "Observe the free‑rider rate among your own faction (agents contributing <10%). "
                "If the rate exceeds 20% in a round, increase your contribution to 100% of your "
                "wallet for the next round to compensate. If the rate is ≤5%, you may lower "
                "your contribution to 80% to conserve resources."
            ),
            "summary": "Adjust contribution based on own‑faction free‑rider rate.",
            "priority": 2,
        },
        {
            "name": "Punish Free‑Riders Aggressively",
            "guidance": (
                "If an agent contributes less than 10% of their endowment for two consecutive "
                "rounds, punish them with amount 15 (you pay 4.5, they lose 15). This stronger "
                "punishment quickly deters repeat free‑riders."
            ),
            "summary": "Stronger punishment of repeat free‑riders.",
            "priority": 3,
        },
        {
            "name": "Broadcast Cooperation Norms",
            "guidance": (
                "At the start of the game and every 4 rounds thereafter, broadcast a concise "
                "message: 'High contributions (≥90%) benefit all. Free‑riders will be punished.'"
            ),
            "summary": "Regularly remind faction of contribution expectations.",
            "priority": 4,
        },
        {
            "name": "Encourage Allies",
            "guidance": (
                "Each round, privately message any teammate who contributed ≥90% of their wallet "
                "with a brief note of appreciation, e.g., 'Thanks for your support!' This reinforces "
                "cooperation without costing resources."
            ),
            "summary": "Privately commend high‑contributing teammates.",
            "priority": 5,
        },
    )


def get_rules_as_dicts():
    """Return rules in OpenEvolve-compatible format."""
    return list(get_constitution_rules())
